import json
from src.nodes.base import BaseNode

class Hou_Mcp_Recommendation_Engine(BaseNode):
    name = "hou_mcp_recommendation_engine"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("intent", "string", widget_type="text", default="")
        self.add_input("operations_json", "string", widget_type="text", default="[]")
        self.add_input("context_json", "string", widget_type="text", default="{}")
        self.add_output("recommended_workflow", "string")
        self.add_output("recommended_template", "string")
        self.add_output("strategies", "any")
        self.add_output("primary_strategy", "string")
        self.add_output("workflow_confidence", "float")
        self.add_output("recommendations_json", "string")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        try:
            from src.runtime.recommendation_engine import get_recommendation_engine
            engine = get_recommendation_engine()

            intent = inputs.get("intent") or ""
            ops_raw = inputs.get("operations_json") or "[]"
            ctx_raw = inputs.get("context_json") or "{}"
            try:
                operations = json.loads(ops_raw) if isinstance(ops_raw, str) else ops_raw
            except json.JSONDecodeError:
                operations = []
            try:
                context = json.loads(ctx_raw) if isinstance(ctx_raw, str) else ctx_raw
            except json.JSONDecodeError:
                context = {}

            wf_rec = engine.recommend_workflow(intent, context) if intent else {}
            tmpl_rec = engine.recommend_template(intent, context) if intent else {}
            strategy_rec = engine.recommend_strategy(operations, context)

            full = {"workflow": wf_rec, "template": tmpl_rec, "strategy": strategy_rec}
            return {
                "recommended_workflow": wf_rec.get("recommended_op") or "",
                "recommended_template": tmpl_rec.get("recommended_template") or "",
                "strategies":           strategy_rec.get("strategies", []),
                "primary_strategy":     strategy_rec.get("primary", ""),
                "workflow_confidence":  wf_rec.get("confidence", 0.0),
                "recommendations_json": json.dumps(full),
                "exec_out": True,
            }
        except Exception as e:
            self.log_error(f"Recommendation engine error: {e}")
            return {"recommended_workflow": "", "recommended_template": "", "strategies": [], "primary_strategy": "", "workflow_confidence": 0.0, "recommendations_json": "{}", "exec_out": True}

def register_node():
    return Hou_Mcp_Recommendation_Engine
